"use client"

import { useState, useEffect } from "react"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { StatsSummary } from "@/components/statistics/stats-summary"
import { WorkloadStats } from "@/components/statistics/workload-stats"
import { ResolutionTimeChart } from "@/components/statistics/resolution-time-chart"
import { api } from "@/lib/api"
import { useToast } from "@/components/ui/use-toast"
import { CalendarIcon, RefreshCw } from "lucide-react"

export default function StatisticsPage() {
  const { toast } = useToast()
  const [loading, setLoading] = useState(true)
  const [loadingWorkload, setLoadingWorkload] = useState(true)
  const [loadingResolution, setLoadingResolution] = useState(true)
  
  const [stats, setStats] = useState({
    totalReclamos: 0,
    tasaResolucion: 0,
    tasaCancelacion: 0,
  })
  
  const [workloadData, setWorkloadData] = useState({
    porArea: [] as Array<{ area: string; cantidad: number; porcentaje: number }>,
    porResponsable: [] as Array<{ responsableId: string; responsableNombre: string; cantidad: number; porcentaje: number }>,
  })

  const [resolutionData, setResolutionData] = useState<Array<{
    tipo: string
    tiempoPromedioDias: number
    cantidadResueltos: number
  }>>([])
  
  // Filtros
  const [fechaInicio, setFechaInicio] = useState("")
  const [fechaFin, setFechaFin] = useState("")
  const [areaFiltro, setAreaFiltro] = useState("")

  const loadStats = async () => {
    try {
      setLoading(true)
      const data = await api.statistics.getResumen(
        fechaInicio || undefined,
        fechaFin || undefined
      )
      setStats(data)
    } catch (error) {
      console.error(error)
      toast({
        title: "Error",
        description: "No se pudieron cargar las estadísticas",
        variant: "destructive",
      })
    } finally {
      setLoading(false)
    }
  }

  const loadWorkload = async () => {
    try {
      setLoadingWorkload(true)
      const data = await api.statistics.getCargaTrabajo(
        fechaInicio || undefined,
        fechaFin || undefined,
        areaFiltro || undefined
      )
      setWorkloadData(data)
    } catch (error) {
      console.error(error)
      toast({
        title: "Error",
        description: "No se pudo cargar la carga de trabajo",
        variant: "destructive",
      })
    } finally {
      setLoadingWorkload(false)
    }
  }

  const loadResolutionTime = async () => {
    try {
      setLoadingResolution(true)
      const data = await api.statistics.getTiempoResolucion()
      setResolutionData(data)
    } catch (error) {
      console.error(error)
      toast({
        title: "Error",
        description: "No se pudo cargar el tiempo de resolución",
        variant: "destructive",
      })
    } finally {
      setLoadingResolution(false)
    }
  }

  useEffect(() => {
    loadStats()
    loadWorkload()
    loadResolutionTime()
  }, [])

  const handleApplyFilters = () => {
    loadStats()
    loadWorkload()
  }

  const handleClearFilters = () => {
    setFechaInicio("")
    setFechaFin("")
    setAreaFiltro("")
    setTimeout(() => {
      loadStats()
      loadWorkload()
    }, 100)
  }

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-3xl font-bold tracking-tight">Estadísticas</h2>
        <p className="text-muted-foreground">
          Análisis y métricas de rendimiento del sistema de reclamos
        </p>
      </div>

      {/* Filtros de Fecha */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <CalendarIcon className="h-5 w-5" />
            Filtros de Período
          </CardTitle>
          <CardDescription>
            Selecciona un rango de fechas para filtrar las estadísticas
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex flex-col sm:flex-row gap-4 items-end">
            <div className="flex-1 space-y-2">
              <Label htmlFor="fechaInicio">Fecha de Inicio</Label>
              <Input
                id="fechaInicio"
                type="date"
                value={fechaInicio}
                onChange={(e) => setFechaInicio(e.target.value)}
              />
            </div>
            <div className="flex-1 space-y-2">
              <Label htmlFor="fechaFin">Fecha de Fin</Label>
              <Input
                id="fechaFin"
                type="date"
                value={fechaFin}
                onChange={(e) => setFechaFin(e.target.value)}
              />
            </div>
            <div className="flex gap-2">
              <Button onClick={handleApplyFilters} disabled={loading}>
                <RefreshCw className={`h-4 w-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
                Aplicar
              </Button>
              <Button 
                variant="outline" 
                onClick={handleClearFilters}
                disabled={loading || (!fechaInicio && !fechaFin)}
              >
                Limpiar
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Resumen de Estadísticas */}
      <div>
        <h3 className="text-lg font-semibold mb-4">Resumen General</h3>
        <StatsSummary
          totalReclamos={stats.totalReclamos}
          tasaResolucion={stats.tasaResolucion}
          tasaCancelacion={stats.tasaCancelacion}
          loading={loading}
        />
      </div>

      {/* Información adicional */}
      {!loading && (fechaInicio || fechaFin) && (
        <Card className="bg-blue-50 dark:bg-blue-950 border-blue-200 dark:border-blue-800">
          <CardContent className="pt-6">
            <p className="text-sm text-blue-800 dark:text-blue-200">
              📊 Mostrando estadísticas 
              {fechaInicio && fechaFin && ` desde ${new Date(fechaInicio).toLocaleDateString()} hasta ${new Date(fechaFin).toLocaleDateString()}`}
              {fechaInicio && !fechaFin && ` desde ${new Date(fechaInicio).toLocaleDateString()}`}
              {!fechaInicio && fechaFin && ` hasta ${new Date(fechaFin).toLocaleDateString()}`}
            </p>
          </CardContent>
        </Card>
      )}

      {/* Explicación de las métricas */}
      <Card>
        <CardHeader>
          <CardTitle>Descripción de Métricas</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <h4 className="font-semibold text-sm mb-1">Total de Reclamos</h4>
            <p className="text-sm text-muted-foreground">
              Cantidad total de reclamos recibidos en el período seleccionado.
            </p>
          </div>
          <div>
            <h4 className="font-semibold text-sm mb-1">Tasa de Resolución</h4>
            <p className="text-sm text-muted-foreground">
              Porcentaje de reclamos que fueron resueltos exitosamente respecto al total.
              Un valor alto indica una buena gestión de reclamos.
            </p>
          </div>
          <div>
            <h4 className="font-semibold text-sm mb-1">Tasa de Cancelación</h4>
            <p className="text-sm text-muted-foreground">
              Porcentaje de reclamos que fueron cancelados respecto al total.
              Un valor bajo es deseable.
            </p>
          </div>
        </CardContent>
      </Card>
    </div>
  )
}
